#!/usr/bin/env python3
"""Freeze a monthly inverse-variance allocation with a 200-day trend eligibility gate."""
from __future__ import annotations
import hashlib,json,subprocess,sys
from datetime import datetime,timezone
from pathlib import Path
import polars as pl
ROOT=Path(__file__).resolve().parents[3];R=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'research/automation'));import registry
MIN=60_000_000_000
assets={}
for asset in ('BTC','ETH'):
 paths=[ROOT/f'data/normalized/binance/{asset}/binance_{asset}_20240916T000000Z_20250916T000000Z_transfer_20261001/spot_bars.parquet',ROOT/f'data/normalized/binance/{asset}/binance_{asset}_20250916T000000Z_20260916T000000Z_archive_20260929/spot_bars.parquet']
 parts=[]
 for p in paths:
  f=pl.read_parquet(p,columns=['open_ts','available_ts','open','close','base_volume','quote_volume','is_closed'])
  assert f.height==365*1440 and f['is_closed'].all() and f['open_ts'].is_sorted()
  assert (f['open_ts'].diff().drop_nulls()==MIN).all() and (f['available_ts']-f['open_ts']==MIN).all()
  parts.append({'path':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size,'rows':f.height})
 assert parts[1]['first_open_ns'] if 'first_open_ns' in parts[1] else True
 assets[asset]={'files':parts,'total_1m_rows':730*1440,'series_start_utc':'2024-09-16T00:00:00Z','series_end_exclusive_utc':'2026-09-16T00:00:00Z'}
filters=json.loads((R/'exchange_filters.json').read_text());assert filters['raw_sha256']==hashlib.sha256((R/'exchange_info_raw.json').read_bytes()).hexdigest()
assert set(filters['symbols'])=={'BTCUSDT','ETHUSDT'}
start='2025-09-19T00:01:00Z';end='2026-09-14T00:01:00Z';Ls=[20,60,120];targets=[0.20,0.30,0.40]
costs={'fee_per_side':0.001,'half_spread_estimate_per_side':0.0001,'slippage_estimate_per_side':0.0002,'impact_model':'0.5 * sample stdev of previous 20 complete UTC daily log returns * sqrt(order quote budget / mean previous 20 complete UTC daily quote ADV)','maximum_ADV_participation':0.001,'multipliers':[1,2,3],'all_terms_scaled_together':True,'cash_yield':0}
signal={'eligibility_gate':'At each scheduled UTC monthly decision, require the previous fully closed UTC daily close to be strictly greater than the simple arithmetic mean of that close and exactly 199 immediately preceding fully closed daily closes (SMA200 includes the signal day). If false, target 0% crypto exposure and hold cash.','volatility_rule':'If eligible, estimate sample stdev of exactly L previous fully closed daily log returns, ending at the previous daily close, and set target asset fraction = min(1, (target annualized volatility / (daily stdev * sqrt(365)))^2). If ineligible, target fraction is 0. No leverage.','schedule':'Initial OOS execution at 2025-09-19T00:01:00Z, then rebalance only at the 00:01 UTC minute on each first UTC calendar day. No intermediate trades; terminal liquidation at 2026-09-14T00:01:00Z.','sizing':'Each 2,000 USDT configuration has independent 1,000-USDT BTC and ETH cash sleeves (raw initial weights 0.5/0.5). Each sleeve targets exposure within its own current NAV and cannot transfer to the other sleeve; each holds only its asset plus residual USDT.','signal_timing':'All calculations use completed UTC daily bars only; the previous day close is available at 00:00 UTC and execution reference is the next 1m open at 00:01 UTC. Historical prices are used only for this offline research backtest, never for current paper10 fills.','execution':'Trade only target delta at scheduled dates. Fee, spread, slippage, impact, filters, participation, tick rounding and lot flooring apply to each partial rebalance. Terminal position is costed to cash.'}
gates={'positive_net_return_all_cost_scenes':True,'positive_1x_folds_minimum':8,'folds':12,'fold_days':30,'max_3x_sampled_drawdown_pct':25,'3x_neighbor_positive_fraction_minimum':0.60,'neighbor_definition':'At most one adjacent grid step on each axis, center included.','minimum_1x_rebalance_fills':4,'gross_reference_pnl_to_1x_cost_minimum':2.5,'zero_rejected_or_capacity_orders':True,'terminal_flat_all_scenes':True}
plan={'round':R.name,'frozen_at_utc':datetime.now(timezone.utc).isoformat().replace('+00:00','Z'),'status':'frozen_before_evaluation','source_repository_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'direction':'200-day trend eligibility gate over monthly inverse-variance BTC/ETH cash sleeves','hypothesis':'A slow absolute trend gate may prevent a monthly volatility-managed long-only sleeve from carrying exposure through a sustained bearish regime. The sizing and gate are fixed before results and are not assumed to create positive alpha.','literature_context':[{'citation':'Moreira & Muir, Volatility Managed Portfolios, NBER Working Paper 22208 (2016).','url':'https://www.nber.org/papers/w22208','accessed_utc':'2026-10-13','scope':'Motivates inverse-variance exposure scaling in equity portfolios; not evidence for BTC/ETH spot or the 200-day gate.'}],'prior_work':{'base_strategy':'research/experiments/20261013T224056Z tested the same monthly inverse-variance sleeves without an SMA gate: 9/9 candidates rejected, best 1x return -5.23%, 5/12 positive folds. This batch changes the economic rule by adding fixed SMA200 exposure eligibility; prior outputs are retained, not tuned.','other_related_families':'Daily SMA volatility ceilings are indicator entry filters, not monthly continuous inverse-variance sizing with a trend eligibility overlay. Relative strength, ratio mean reversion, volatility compression, and 4h momentum were rejected in their stored reports.','initial16_audit':'research/experiments/20261012T035429Z/prior_evidence_audit.json found actual backtest evidence for all initial 16; no eligible code-only configuration remains.'},'data':{'exchange':'Binance spot archived 1m OHLCV aggregated into UTC daily closes/volumes; input series hashes in data_manifest.json','assets':assets,'start_utc':start,'end_exclusive_utc':end,'oos_days':360,'folds':12,'fold_days':30,'history_reused':True,'holdout_note':'2025-09-19..2026-09-14 has been reused extensively and is not an untouched final holdout. No model is fitted.'},'portfolio':{'capital_per_configuration_usdt':2000,'raw_initial_weights':[0.5,0.5],'initial_cash_per_sleeve_usdt':1000,'meaning':'Independent BTC/ETH initial cash sleeves; SMA and volatility exposure scales each sleeve’s current NAV only. No transfer, normalization across sleeves, leverage, shorting or interest on cash.'},'rule':signal,'grid':{'sma_gate_days':200,'realized_vol_lookback_days':Ls,'target_annual_volatility':targets,'monthly_rebalance_only':True,'parameter_sensitivity':'Full 3x3 grid over realized volatility lookback and target annualized volatility; local neighbors are one adjacent grid step.'},'cost_model':costs,'exchange_snapshot':{'snapshot_at_utc':filters['snapshot_at_utc'],'path':f'research/experiments/{R.name}/exchange_filters.json','raw_path':f'research/experiments/{R.name}/exchange_info_raw.json','raw_sha256':filters['raw_sha256']},'predeclared_failure_gates':gates,'benchmark_read_only':{'source_report':'research/experiments/20261013T224056Z/report.json','configuration':'hold_360d_BTC_ETH_50_50_monthly_volmanaged','note':'Exact same dates, starting sleeves, fees and 50/50 buy-and-hold method; reuse completed comparator instead of repeating the same config.'}}
plan['_sha256']=registry.digest(plan);(R/'plan.json').write_text(json.dumps(plan,indent=2,ensure_ascii=False)+'\n')
batch=[]
for L in Ls:
 for v in targets:
  name=f'sma200_volmanaged_L{L}_V{int(v*100):02d}'
  spec={'kind':'strategy','family':'spot-sma-gated-monthly-volatility-managed-sleeves','market':'spot','universe':['BTC/USDT','ETH/USDT'],'timeframe':'1d','logic':signal,'parameters':{'sma_gate_days':200,'realized_vol_lookback_days':L,'target_annual_volatility':v,'rebalance_schedule':'initial OOS then first UTC calendar day at 00:01; no intermediate orders','initial_capital_usdt':2000,'raw_initial_weights':[0.5,0.5],'per_asset_initial_cash_usdt':1000,'start_utc':start,'end_exclusive_utc':end,'folds':12,'fold_days':30,'cost_multipliers':[1,2,3],'fee_per_side':0.001,'half_spread_estimate_per_side':0.0001,'slippage_estimate_per_side':0.0002,'maximum_ADV_participation':0.001,'exchange_info_raw_sha256':filters['raw_sha256']},'name':name,'validation_plan':f'research/experiments/{R.name}/plan.json'}
  p=R/'specs'/f'{name}.json';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(spec,indent=2,ensure_ascii=False)+'\n');batch.append({'name':name,'spec':str(p.relative_to(ROOT)),'role':'candidate'})
(R/'batch.json').write_text(json.dumps(batch,indent=2,ensure_ascii=False)+'\n')
records=registry.read_records(ROOT/'research/automation/registry.jsonl');fps=set()
for row in batch:
 s=json.loads((ROOT/row['spec']).read_text());fp=registry.fingerprint(s);assert fp not in fps;fps.add(fp)
 old=records.get(fp);assert not (old and old.get('result_available') is True),row['name']
print(json.dumps({'frozen':True,'plan_sha256':hashlib.sha256((R/'plan.json').read_bytes()).hexdigest(),'candidate_count':9,'initial16_no_missing_results':True,'exact_duplicates':0},ensure_ascii=False))
